function pasteboardForType(type) {
  if (type === undefined || type === null || type === "" || type === "clipboard" || type === "selection" || type === "general") {
    return $.NSPasteboard.generalPasteboard;
  }

  switch (type) {
    case "find":
      return $.NSPasteboard.pasteboardWithName($.NSPasteboardNameFind);
    case "drag":
      return $.NSPasteboard.pasteboardWithName($.NSDragPboard);
    case "font":
      return $.NSPasteboard.pasteboardWithName($.NSPasteboardNameFont);
    case "ruler":
      return $.NSPasteboard.pasteboardWithName($.NSPasteboardNameRuler);
    default:
      return $.NSPasteboard.pasteboardWithName(type);
  }
}

function unwrapString(value) {
  if (value === undefined || value === null) {
    return "";
  }

  const unwrapped = ObjC.unwrap(value);
  return unwrapped === undefined || unwrapped === null ? "" : String(unwrapped);
}

function isNil(value) {
  if (value === undefined || value === null) {
    return true;
  }

  const unwrapped = ObjC.unwrap(value);
  return unwrapped === undefined || unwrapped === null;
}

function pasteboardTypeForFormat(format) {
  switch (String(format)) {
    case "text/plain":
    case "public/utf8-plain-text":
    case "public.utf8-plain-text":
    case "NSStringPboardType":
      return $.NSPasteboardTypeString;
    case "text/html":
    case "public/html":
    case "public.html":
      return $.NSPasteboardTypeHTML;
    case "text/rtf":
    case "application/rtf":
    case "public/rtf":
    case "public.rtf":
      return $.NSPasteboardTypeRTF;
    case "image/png":
    case "public/png":
    case "public.png":
      return $.NSPasteboardTypePNG;
    case "image/tiff":
    case "public/tiff":
    case "public.tiff":
      return $.NSPasteboardTypeTIFF;
    case "text/uri-list":
    case "public/url":
    case "public.url":
    case "NSURLPboardType":
      return $.NSPasteboardTypeURL;
    case "public/file-url":
    case "public.file-url":
      return $.NSPasteboardTypeFileURL;
    default:
      return String(format);
  }
}

function pasteboardTypesForFormat(format) {
  if (String(format) === "text/uri-list") {
    return [$.NSPasteboardTypeURL, $.NSPasteboardTypeFileURL];
  }

  return [pasteboardTypeForFormat(format)];
}

function publicNameForType(type) {
  switch (String(ObjC.unwrap(type))) {
    case "public.utf8-plain-text":
      return "text/plain";
    case "public.html":
      return "text/html";
    case "public.rtf":
      return "text/rtf";
    case "public.png":
      return "image/png";
    case "public.tiff":
      return "image/tiff";
    case "public.url":
    case "public.file-url":
      return "text/uri-list";
    default:
      return String(ObjC.unwrap(type));
  }
}

function availableFormats(pasteboard) {
  const types = pasteboard.types;
  const formats = [];
  if (types === undefined || types === null) {
    return formats;
  }

  for (let i = 0; i < types.count; i += 1) {
    formats.push(publicNameForType(types.objectAtIndex(i)));
  }

  return formats;
}

function hasType(pasteboard, type) {
  const typeName = String(ObjC.unwrap(type));
  const types = pasteboard.types;
  if (types !== undefined && types !== null) {
    for (let i = 0; i < types.count; i += 1) {
      if (String(ObjC.unwrap(types.objectAtIndex(i))) === typeName) {
        return true;
      }
    }
  }

  return !isNil(pasteboard.dataForType(type)) || !isNil(pasteboard.stringForType(type));
}

function firstDataForTypes(pasteboard, types) {
  for (const type of types) {
    const data = pasteboard.dataForType(type);
    if (!isNil(data)) {
      return data;
    }
  }

  return null;
}

function firstDataAndTypeForTypes(pasteboard, types) {
  for (const type of types) {
    const data = pasteboard.dataForType(type);
    if (!isNil(data)) {
      return { data, type };
    }
  }

  return null;
}

function firstStringForTypes(pasteboard, types) {
  for (const type of types) {
    const text = pasteboard.stringForType(type);
    if (!isNil(text)) {
      return unwrapString(text);
    }
  }

  return null;
}

function utf8StringForData(data) {
  if (isNil(data)) {
    return "";
  }

  const value = $.NSString.alloc.initWithDataEncoding(data, $.NSUTF8StringEncoding);
  return unwrapString(value);
}

function base64ForString(text) {
  const data = $(String(text)).dataUsingEncoding($.NSUTF8StringEncoding);
  return unwrapString(data.base64EncodedStringWithOptions(0));
}

function base64ForData(data) {
  return isNil(data) ? "" : unwrapString(data.base64EncodedStringWithOptions(0));
}

